"""Prepare six character reference views per supplied identity."""
from pathlib import Path
import json,shutil
ROOT=Path(__file__).resolve().parents[1]
SOURCES={
'creator':'/Users/ihor.buts/.codex/generated_images/01a158a2-788e-7540-81d2-d4a72e823195/exec-6f150fe8-9eb5-4500-8359-d020df7924bf.png',
'barista':'/Users/ihor.buts/.codex/generated_images/01a158a2-788e-7540-81d2-d4a72e823195/exec-2f39787d-c265-4a7d-8fab-e34ce45985de.png'}
IDENTITY={
'creator':'''The main WOMAN in the supplied cafe entrance image, not the man in its background. Preserve her exact friendly adult face, warm medium-tan skin, big simple dark eyes and brows, soft rounded nose and subtle smile, thick dark-brown sculpted wavy high ponytail, and small gold stud earrings. Preserve her sunny-yellow short-sleeve crewneck T-shirt with softly turned sleeve edges, tucked into sage-green high-waisted tapered trousers with one small gold button. Preserve the dusty-pink crossbody bag with a rounded flap and round gold fastening: the bag is on HER ANATOMICAL RIGHT HIP and the strap goes over HER ANATOMICAL LEFT SHOULDER, consistently in every view. Complete the partly hidden lower legs with the same sage trousers and simple off-white low-top sneakers with cream soles and no logos. No apron or barista outfit.''',
'barista':'''The main MAN beside the espresso machine in the supplied image, not the female visitor from another image. Preserve his exact friendly adult face, warm light peach-tan skin, simple large dark eyes/brows, subtle closed smile, rounded nose, and thick short dark-brown swept sculpted wavy hair. Preserve his ivory/white short-sleeve crewneck T-shirt and sage-green bib apron with bright sunny-yellow shoulder straps and round gold/yellow front fasteners. Keep a simple sage front patch pocket. Complete the hidden lower outfit with a knee-length sage apron, charcoal straight trousers and plain off-white low-top sneakers with cream soles and no logos. On the back the yellow shoulder straps cross once and the sage waist ties form a simple flat bow; preserve this construction in every view. No pink bag, ponytail or female outfit.'''}
VIEWS={
'front':'EXACT FRONT elevation: camera at body mid-height directly in front, zero yaw and zero pitch. Character faces straight toward camera. Entire head, hands and shoe soles edge visible, no three-quarter angle.',
'back':'EXACT BACK elevation: camera at body mid-height directly behind. Character faces away, back of head/hair, clothing and back of shoes visible. No visible face or three-quarter turn.',
'left':'EXACT ANATOMICAL LEFT SIDE elevation: camera directly on the character\'s LEFT side, true 90-degree profile, face/nose points toward the LEFT edge of the image. No three-quarter face. Keep bag/apron details on their real anatomical sides, not mirrored.',
'right':'EXACT ANATOMICAL RIGHT SIDE elevation: camera directly on the character\'s RIGHT side, true 90-degree profile, face/nose points toward the RIGHT edge of the image. No three-quarter face. Keep bag/apron details on their real anatomical sides, not mirrored.',
'top':'EXACT TOP orthographic projection: camera directly ABOVE the upright standing character, looking vertically down. Correctly show crown/ponytail, shoulders, upper arms/hands and the shoes only where naturally unoccluded. The character is still upright in the same neutral A-pose, not lying down. Anatomical front points toward the BOTTOM of the image. Respect self-occlusion; do not fake a frontal portrait or tilt the camera to make the face visible.',
'bottom':'EXACT BOTTOM orthographic projection: camera directly BELOW the upright standing character, looking vertically upward. Shoe SOLES and the naturally occluded underside silhouette of the trousers, arms, chin and hair are the relevant shapes. The character is fully clothed and upright in the identical neutral A-pose, never lying down or doing a pose. Anatomical front points toward the TOP of the image. Respect self-occlusion: feet/trousers can block much of the upper body. No oblique worm-eye perspective or frontal portrait.'}
COMMON='''Use case: character model reference. Generate ONE precise orthographic character reference image from the requested view, using the supplied image as IDENTITY, CLOTHING, HAIR, PROPORTIONS and MATERIAL reference only. Premium cohesive friendly soft 3D clay/plastic, smooth matte and semi-matte surfaces, simplified facial features and sculpted hair, softly oversized adult head, rounded natural anatomy, matching the reference exactly. One character only; no cafe, counter, cup, plant, furniture, pictured camera, scenery, text, labels, numerals, logos, watermark or UI. Warm off-white seamless solid background, even soft neutral studio illumination, no dramatic cast shadow. Use an orthographic camera with no perspective and one shared scale/magnification across the six views, enough canvas to fit the whole standing figure in front/back views. Square canvas, ideally 1536 x 1536. Top/bottom naturally occupy less vertical space; do not zoom or tilt them to fill the canvas. Standard neutral symmetrical A-pose throughout: standing upright with level head, relaxed shoulders, arms 20 degrees away from torso, straight elbows, relaxed open fingers, palms facing thighs, feet hip-width and parallel. Exactly one coherent body, two arms, two legs, at most two visible hands with five natural fingers each; no duplicated limbs. No pose, expression, proportion, hairstyle, clothing, bag or color changes between views. This is a reusable reference asset, not a scene illustration.'''
entries=[]
for character,source in SOURCES.items():
 folder=ROOT/character;folder.mkdir(parents=True,exist_ok=True);shutil.copy2(source,folder/'source.png')
 (folder/'prompts').mkdir(exist_ok=True);(folder/'originals').mkdir(exist_ok=True)
 for view,description in VIEWS.items():
  prompt=f'{COMMON}\nIDENTITY: {IDENTITY[character]}\nREQUIRED VIEW: {description}\nMake the requested camera direction unmistakable; it is more important than repeating the source picture\'s pose or camera angle. Preserve the exact original character identity.'
  (folder/'prompts'/f'{view}.txt').write_text(prompt+'\n')
  entries.append(dict(character=character,view=view,source=source,prompt=prompt,status='pending'))
queue=[f'{c}.front' for c in SOURCES]+[f'{c}.{v}' for c in SOURCES for v in VIEWS if v!='front']
manifest=dict(version=1,date='2026-10-28',views_per_character=6,total_views=12,characters=list(SOURCES),queue=queue,entries=entries,source_images_preserved=True,lower_outfit_notes='Shoes, lower trousers and the hidden apron-back construction are consistent design completions where the scene references do not show them.')
if (ROOT/'manifest.json').exists():raise SystemExit('Already prepared; resume existing manifest.')
(ROOT/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
(ROOT/'README.md').write_text('# Loca character model references\n\nSix views for each supplied character: front, back, anatomical left, anatomical right, top and bottom. The `creator/` and `barista/` folders contain the individual PNGs, original tool outputs, source scene image and exact prompts.\n\nThe same neutral A-pose, clothing, hair and shared orthographic scale are requested in all views. Top and bottom are true vertical projections, with natural self-occlusion. Left/right are the character\'s anatomical sides. No environment, labels, lettering or UI are included in the images.\n\nLower legs, unbranded off-white shoes and the hidden apron-back straps/ties are coherent design completions because the supplied scene pictures do not expose every surface. The creator\'s pink bag stays on her right hip, with its strap over her left shoulder.\n\nThese are generated image references for modelling, not a rigged 3D mesh or a dimensionally certified CAD turnaround. `manifest.json` records exact prompts, inputs and output provenance.\n')
print('MODEL_REFERENCES_PREPARED',len(entries))
if __name__=='__main__':pass
